-- ============================================================
-- V10__seed_sample_data.sql
-- Development/demo seed data — all UUIDs are auto-generated by
-- PostgreSQL's gen_random_uuid() default. Relations are chained
-- via CTEs (RETURNING) within a single INSERT, or via natural-key
-- joins (license_plate, email) across separate statements once
-- prior rows are visible within the same migration transaction.
-- ============================================================

-- ---------------------------------
-- FLEETS (3)
-- ---------------------------------
INSERT INTO fleet (name, created_at)
SELECT name, created_at
FROM (VALUES
    ('Flotte Nord',              NOW() - INTERVAL '120 days'),
    ('Flotte Sud',                NOW() - INTERVAL '90 days'),
    ('Flotte Logistique Paris',   NOW() - INTERVAL '60 days')
) AS f(name, created_at)
WHERE NOT EXISTS (
    SELECT 1 FROM fleet WHERE fleet.name = f.name
);

